export const DisplayPolicy = Schema.Struct({ "capture_monitor": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Stream this physical connector (`DP-1`, `HDMI-A-2`) instead of a\nvirtual display; `None` is the virtual path. Host-wide, orthogonal\nto `preset`. `PUNKTFUNK_CAPTURE_MONITOR` overrides it so `host.env`\ncan pin without a console write undoing it." })), "ddc_power_off": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Windows: DDC/CI panel off (VCP 0xD6) before Exclusive isolate, on at\nrestore. Cuts standby auto-input-scan / DP link churn on a dark\nphysical. Best-effort; no DDC/CI → skip. Orthogonal to `preset`; default off." })), "edid_lock": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Windows/AMD: pin connector EDID emulation while streaming\n(`pf_win_display::adl_emul`). Locked at first Exclusive isolate\nbefore physicals deactivate (awake sink answers the live-EDID read),\nunlocked at last-member teardown, crash-journaled. Inert without\n`atiadlxx.dll`. Orthogonal to `preset`; default off." })), "game_session": Schema.optionalKey(Schema.Literals(["auto", "dedicated"]).annotate({ "description": "Game-launch routing. Orthogonal to `preset`; `#[serde(default)]` is\n`Auto` so older `display-settings.json` files stay untouched." })), "identity": Schema.optionalKey(Identity), "keep_alive": Schema.optionalKey(KeepAlive), "layout": Schema.optionalKey(Layout), "max_displays": Schema.optionalKey(Schema.Number.annotate({ "description": "Simultaneous live virtual displays. Clamped to `1..=16` (connector ceiling).", "format": "int32" }).check(Schema.isInt()).check(Schema.isGreaterThanOrEqualTo(0))), "mode_conflict": Schema.optionalKey(ModeConflict), "pnp_disable_monitors": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Windows: disable the operator's physical monitor PnP nodes for the\nstream and re-enable at teardown. Persistent so a re-HPD stays off.\nOpt-in. Inactive externals are default-on via\n[`standby_sink_neutralise`]; this flag still implies that. A crash\njournal re-enables leftovers. Orthogonal to `preset`; default off." })), "preset": Schema.optionalKey(Preset), "topology": Schema.optionalKey(Topology), "version": Schema.optionalKey(Schema.Number.annotate({ "description": "Schema version. Unknown versions load best-effort\n([`DisplayPolicyStore::load_from`] warns) and write pins current.", "format": "int32" }).check(Schema.isInt()).check(Schema.isGreaterThanOrEqualTo(0))) }).annotate({ "description": "File + mgmt GET/PUT shape. When [`preset`](Self::preset) is not\n[`Preset::Custom`], explicit fields are ignored; [`effective`](Self::effective)\nresolves both to [`EffectivePolicy`]." });
